return items.map(item => {
  const job = item.json;

  const location = job.location || '';
  const pay = job.salary || job.compensation || 'N/A';

  // ── CONFIGURE: Job title keywords to INCLUDE ─────────────────────────────
  const relevantTitles = [
    /automation/i,
    /process improvement/i,
    /digital transformation/i,
    /operations/i,
    /\bai\b/i,
    // Add more patterns matching YOUR target role, e.g.:
    // /supply chain/i,
    // /data analyst/i,
  ];
  // ─────────────────────────────────────────────────────────────────────────

  const isMatch = relevantTitles.some(regex => regex.test(job.title || job.position || ''));

  const postDate = new Date(job.date);
  const hoursSincePost = (Date.now() - postDate) / 1000 / 60 / 60;
  const isRecent = hoursSincePost <= 24;

  if (!isMatch || !isRecent) return null;

  return {
    json: {
      title: job.title || job.position || '',
      company: job.company,
      description: job.description,
      link: job.url,
      location: location,
      date: job.date,
      pay: pay,
    }
  };
}).filter(item => item !== null);

