});

return items.map(item => {
  const rawOutput = item.json.output;
  let parsedJson;

  try {
    const cleaned = rawOutput
      .replace(/^```json\s*/i, '')
      .replace(/```$/, '')

    parsedJson = JSON.parse(cleaned);
  } catch (error) {
    console.error("Failed to parse AI JSON output. Error:", error.message);
    console.error("Problematic Raw Output:", rawOutput);

    parsedJson = {
      error: "Invalid JSON from AI",
      raw_ai_output: rawOutput,
      title: item.json.title || "N/A",
      company: item.json.company || "N/A",
      link: item.json.link || "N/A"
    };
  }

  const now = new Date();
  const mmddyyyy = `${(now.getMonth() + 1).toString().padStart(2,    '0')}/${now.getDate().toString().padStart(2, '0')}/${now.getFullYear()}`;

  parsedJson.savedAt = mmddyyyy;

  delete parsedJson._preferenceContext;
  delete parsedJson.baseScore;
  delete parsedJson.preferenceBoost;
  delete parsedJson.preferenceProfile;


  return { json: parsedJson };
});

