// Build Preference Profile from Applied Jobs
const allRows = items.map(i => i.json);
const appliedRows = allRows.filter(row =>
  (row['Applied?'] || '').toString().trim().toUpperCase() === 'Y'
);

if (appliedRows.length === 0) {
  return [{
    json: {
      preferenceProfile: {
        isEmpty: true,
        appliedCount: 0,
        titleKeywords: {},
        titlePhrases: {},
        companyNames: [],
        industrySignals: {},
        salaryRange: { min: null, max: null },
        topSources: {},
        avgConfidence: null,
        summaryText: "No applied jobs yet. No preference boosting applied."
      }
    }
  }];
}

const stopWords = new Set([
  'the','a','an','and','or','of','for','in','at','to','with','&','-','–','/',',',
  'this','that','will','are','has','have','been','from','they','their','our','you',
  'your','about','into','not','all','can','but','who','what','how','also','than',
  'its','more','other','some','such','new','one','two','may','must','should','would'
]);

const titleWordFreq = {};
for (const row of appliedRows) {
  const title = (row['Job Title'] || '').toLowerCase();
  const words = title.split(/[\s\-\/,&]+/).filter(w => w.length > 2 && !stopWords.has(w));
  for (const word of words) {
    titleWordFreq[word] = (titleWordFreq[word] || 0) + 1;
  }
}

const titlePhraseFreq = {};
for (const row of appliedRows) {
  const title = (row['Job Title'] || '').toLowerCase().trim();
  const words = title.split(/\s+/);
  for (let i = 0; i < words.length - 1; i++) {
    if (!stopWords.has(words[i]) && !stopWords.has(words[i+1]) && words[i].length > 2 && words[i+1].length > 2) {
      const bigram = `${words[i]} ${words[i+1]}`;
      titlePhraseFreq[bigram] = (titlePhraseFreq[bigram] || 0) + 1;
    }
  }
}

const companyNames = [...new Set(
  appliedRows.map(r => (r['Company Name'] || '').trim()).filter(Boolean)
)];

const descriptionWordFreq = {};
for (const row of appliedRows) {
  const text = `${row['AI Summary'] || ''} ${row['Fit Reason'] || ''} ${row['Matched Keywords'] || ''}`.toLowerCase();
  const words = text.split(/[\s,;|]+/).filter(w => w.length > 3 && !stopWords.has(w));
  for (const word of words) {
    descriptionWordFreq[word] = (descriptionWordFreq[word] || 0) + 1;
  }
}
const minFreq = appliedRows.length < 5 ? 1 : 2;
const industrySignals = {};
for (const [word, count] of Object.entries(descriptionWordFreq)) {
  if (count >= minFreq) {
    industrySignals[word] = count;
  }
}

let salaryMin = Infinity;
let salaryMax = 0;
for (const row of appliedRows) {
  const pay = (row['Pay'] || '').toString();
  const matches = [...pay.matchAll(/\$?([\d,]+)/g)];
  for (const m of matches) {
    const val = parseInt(m[1].replace(/,/g, ''), 10);
    if (val > 1000) {
      if (val < salaryMin) salaryMin = val;
      if (val > salaryMax) salaryMax = val;
    }
  }
}

const sourceFreq = {};
for (const row of appliedRows) {
  const src = (row['source'] || '').trim();
  if (src) sourceFreq[src] = (sourceFreq[src] || 0) + 1;
}

const confidences = appliedRows
  .map(r => parseFloat(r['AI Confidence']))
  .filter(n => !isNaN(n));
const avgConfidence = confidences.length > 0
  ? Math.round(confidences.reduce((a, b) => a + b, 0) / confidences.length)
  : null;

const topTitleWords = Object.entries(titleWordFreq)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 10)
  .map(([w, c]) => `${w}(${c})`);

const topPhrases = Object.entries(titlePhraseFreq)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([p, c]) => `"${p}"(${c})`);

const topIndustry = Object.entries(industrySignals)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 10)
  .map(([w, c]) => `${w}(${c})`);

const summaryText = [
  `User has applied to ${appliedRows.length} jobs so far.`,
  `Top title keywords: ${topTitleWords.join(', ') || 'none yet'}.`,
  `Common title phrases: ${topPhrases.join(', ') || 'none yet'}.`,
  `Companies applied to: ${companyNames.slice(0, 10).join(', ')}.`,
  `Top industry signals: ${topIndustry.join(', ') || 'none yet'}.`,
  salaryMin !== Infinity ? `Salary range of applied jobs: $${salaryMin.toLocaleString()} - $${salaryMax.toLocaleString()}.` : '',
  `Average AI confidence of applied jobs: ${avgConfidence || 'N/A'}.`
].filter(Boolean).join(' ');

return [{
  json: {
    preferenceProfile: {
      isEmpty: false,
      appliedCount: appliedRows.length,
      titleKeywords: titleWordFreq,
      titlePhrases: titlePhraseFreq,
      companyNames,
      industrySignals,
      salaryRange: {
        min: salaryMin === Infinity ? null : salaryMin,
        max: salaryMax === 0 ? null : salaryMax
      },
      topSources: sourceFreq,
      avgConfidence,
      summaryText
    }
  }
}];

// ── CONFIGURE THIS ──────────────────────────────────────────────────────────
const ALLOWED_LOCATIONS = [
  'remote', 'work from home', 'wfh', 'anywhere', 'distributed', 'hybrid',
  'san francisco', 'oakland', 'san jose', 'berkeley', 'palo alto',
  'mountain view', 'sunnyvale', 'santa clara', 'fremont', 'hayward',
  'california', ', ca',
];
// ─────────────────────────────────────────────────────────────────────────────

return items.filter(item => {
  const loc = (item.json.location || '').toLowerCase();
  const title = (item.json.title || '').toLowerCase();
  const combined = loc + ' ' + title;

  if (combined.includes('remote') || combined.includes('work from home') || combined.includes('wfh')) {
    return true;
  }

  return ALLOWED_LOCATIONS.some(allowed => combined.includes(allowed));
});
